cat > app/views/moderate/quizzes/show.html.erb <<'EOF'
<% content_for :title, "#{@quiz.title} · Quizzy" %>
<div class="breadcrumbs"><%= link_to "← All quizzes", moderate_root_path %></div>
<div class="page-head">
  <div>
    <h1><%= @quiz.title %></h1>
    <div class="meta mt-2"><%= @questions.count(&:active?) %> of <%= pluralize(@questions.size, "question") %> active · <%= link_to "Settings", edit_moderate_quiz_path(@quiz) %></div>
  </div>
  <div class="buttons"><%= link_to "Preview", preview_moderate_quiz_path(@quiz), class: "btn btn--ghost" %></div>
</div>
<section class="section mt-0" aria-labelledby="questions-heading">
  <div class="section-head">
    <h2 id="questions-heading">Questions</h2>
    <%= link_to "Add question", new_moderate_quiz_question_path(@quiz), class: "btn" %>
  </div>
  <% if @questions.empty? %>
    <div class="empty">
      <h3>Let’s get them thinking.</h3>
      <p>No questions yet. Add a question to get started.</p>
    </div>
  <% else %>
    <ol class="question-list">
      <% active_number = 0 %>
      <% @questions.each_with_index do |question, index| %>
        <% active_number += 1 if question.active? %>
        <li id="question_<%= question.id %>" class="card question-item <%= 'question-item--inactive' unless question.active? %>">
          <div class="question-item__num" aria-hidden="true"><%= question.active? ? active_number : "—" %></div>
          <div class="question-item__content">
            <div class="question-item__body"><%= question.body %></div>
            <ul class="question-item__options">
              <% question.options.each_with_index do |option, option_index| %>
                <li class="<%= 'is-correct' if option['correct'] %>"><%= option_letter(option_index) %>. <%= option["text"] %><% if option["correct"] %><span class="visually-hidden"> (correct)</span><% end %></li>
              <% end %>
            </ul>
          </div>
          <div class="question-item__actions">
            <div class="buttons">
              <%= button_to "↑", move_up_moderate_quiz_question_path(@quiz, question), method: :patch, class: "btn btn--ghost btn--icon", aria: { label: "Move up" }, title: "Move up", disabled: index.zero? %>
              <%= button_to "↓", move_down_moderate_quiz_question_path(@quiz, question), method: :patch, class: "btn btn--ghost btn--icon", aria: { label: "Move down" }, title: "Move down", disabled: index == @questions.size - 1 %>
            </div>
            <%= form_with model: question, url: toggle_moderate_quiz_question_path(@quiz, question), method: :patch, data: { auto_submit: true } do |form| %>
              <label class="checkbox" for="active_<%= question.id %>">
                <%= form.check_box :active, id: "active_#{question.id}" %> Active
              </label>
            <% end %>
            <div class="buttons">
              <%= link_to "Edit", edit_moderate_quiz_question_path(@quiz, question), class: "btn btn--sm" %>
              <%= button_to "Delete", moderate_quiz_question_path(@quiz, question), method: :delete, class: "btn btn--sm btn--danger", form: { data: { confirm: "Delete this question? This cannot be undone." } } %>
            </div>
          </div>
        </li>
      <% end %>
    </ol>
  <% end %>
</section>
EOF
