cat > app/assets/javascripts/application.js <<'EOF'
// Standard Rails forms handle persistence. No third-party scripts or services.
document.addEventListener("submit", (event) => {
  const message = event.target.dataset.confirm;
  if (message && !window.confirm(message)) event.preventDefault();
});

document.addEventListener("change", (event) => {
  if (event.target.matches("form[data-auto-submit] input[type=checkbox]")) {
    event.target.form.requestSubmit();
  }
});

const questionForm = document.querySelector("[data-question-form]");
if (questionForm) {
  const rows = questionForm.querySelector(".option-rows");
  const template = questionForm.querySelector("template");
  const renumber = () => {
    rows.querySelectorAll(".option-row").forEach((row, index) => {
      const number = index + 1;
      const text = row.querySelector("input[type=text]");
      text.name = `question[option_rows][${index}][text]`;
      text.id = `option_${index}_text`;
      text.placeholder = `Option ${number}`;
      text.setAttribute("aria-label", `Option ${number}`);
      row.querySelector("input[type=hidden]").name = `question[option_rows][${index}][correct]`;
      const checkbox = row.querySelector("input[type=checkbox]");
      checkbox.name = `question[option_rows][${index}][correct]`;
      checkbox.id = `option_${index}_correct`;
      checkbox.setAttribute("aria-label", `Option ${number} is correct`);
      row.querySelector("label").htmlFor = checkbox.id;
      const remove = row.querySelector("button");
      remove.setAttribute("aria-label", `Remove option ${number}`);
      remove.title = `Remove option ${number}`;
    });
  };
  questionForm.querySelector("[data-add-option]").addEventListener("click", () => {
    rows.append(template.content.cloneNode(true));
    renumber();
    rows.lastElementChild.querySelector("input[type=text]").focus();
  });
  rows.addEventListener("click", (event) => {
    const remove = event.target.closest("[data-remove-option]");
    if (!remove) return;
    const row = remove.closest(".option-row");
    const adjacent = row.nextElementSibling || row.previousElementSibling;
    row.remove();
    renumber();
    (adjacent?.querySelector("input[type=text]") || questionForm.querySelector("[data-add-option]")).focus();
  });
}

// Preview state exists only in this closure. No cookies, storage, or answer requests.
const preview = document.querySelector("[data-preview]");
if (preview) {
  const questions = JSON.parse(preview.dataset.questions);
  const questionSection = preview.querySelector("[data-preview-question]");
  const resultSection = preview.querySelector("[data-preview-result]");
  const emptySection = preview.querySelector("[data-preview-empty]");
  const progress = preview.querySelector("[data-progress]");
  const title = preview.querySelector("#preview-question-title");
  const options = preview.querySelector("[data-preview-options]");
  const feedback = preview.querySelector("[data-feedback]");
  const next = preview.querySelector("[data-next]");
  const scoreTitle = preview.querySelector("[data-score]");
  let index = 0;
  let score = 0;
  let answered = false;

  const showQuestion = (focus = false) => {
    resultSection.hidden = true;
    emptySection.hidden = questions.length > 0;
    questionSection.hidden = questions.length === 0;
    if (!questions.length) return;
    answered = false;
    const question = questions[index];
    progress.textContent = `Question ${index + 1} of ${questions.length}`;
    title.textContent = question.body;
    feedback.hidden = true;
    next.hidden = true;
    next.textContent = index === questions.length - 1 ? "See score" : "Next question";
    options.className = "play-options";
    options.replaceChildren();
    question.options.forEach((option, optionIndex) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "play-option";
      button.setAttribute("aria-label", option.text);
      const letter = document.createElement("span");
      letter.className = "play-option__letter";
      letter.setAttribute("aria-hidden", "true");
      letter.textContent = optionIndex < 26 ? String.fromCharCode(65 + optionIndex) : optionIndex + 1;
      const text = document.createElement("span");
      text.className = "play-option__title";
      text.textContent = option.text;
      button.append(letter, text);
      button.addEventListener("click", () => {
        if (answered) return;
        answered = true;
        if (option.correct) score += 1;
        options.classList.add("is-locked", "is-revealed");
        Array.from(options.children).forEach((choice, choiceIndex) => {
          choice.disabled = true;
          choice.classList.toggle("is-picked", choiceIndex === optionIndex);
          if (question.options[choiceIndex].correct) {
            choice.classList.add("is-correct");
            const mark = document.createElement("span");
            mark.className = "play-option__mark";
            mark.textContent = "✓ Correct";
            choice.append(mark);
            choice.setAttribute("aria-label", `${question.options[choiceIndex].text} (correct)`);
          }
        });
        feedback.textContent = option.correct ? "Correct!" : "Wrong!";
        feedback.className = `play-status ${option.correct ? "play-status--correct" : "play-status--wrong"}`;
        feedback.hidden = false;
        next.hidden = false;
        next.focus();
      });
      options.append(button);
    });
    if (focus) title.focus();
  };

  next.addEventListener("click", () => {
    if (!answered) return;
    if (index < questions.length - 1) {
      index += 1;
      showQuestion(true);
    } else {
      questionSection.hidden = true;
      resultSection.hidden = false;
      scoreTitle.textContent = `Score: ${score}/${questions.length}`;
      scoreTitle.focus();
    }
  });
  const restart = () => {
    index = 0;
    score = 0;
    showQuestion(true);
  };
  preview.querySelector("[data-restart]").addEventListener("click", restart);
  // A page restored from the back/forward cache must also start fresh.
  window.addEventListener("pageshow", (event) => { if (event.persisted) restart(); });
  showQuestion();
}
EOF
